package com.profa.job;import jakarta.persistence.*;import java.time.*;import java.util.*;@Entity@Table(name="applications")public class Application{@Id@GeneratedValue(strategy=GenerationType.UUID)UUID id;UUID jobId;UUID teacherId;String status="NEW";String coverLetter;Instant createdAt=Instant.now();public UUID getId(){return id;}public UUID getJobId(){return jobId;}public void setJobId(UUID v){jobId=v;}public UUID getTeacherId(){return teacherId;}public void setTeacherId(UUID v){teacherId=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public String getCoverLetter(){return coverLetter;}public void setCoverLetter(String v){coverLetter=v;}}